"""Compiles the private hidden question set into a frozen, importable native
module so `hidden_questions.json` never sits on disk as readable text.

Organizer-only build step. Mirrors the technique CPython's own frozen-module
importer uses (a marshaled code object executed inside a module's namespace),
packaged as a small self-contained C extension so it doesn't require building
a custom `python` interpreter (the classic Tools/freeze workflow):

    private/hidden_questions.json  --(this script)-->  assets/_hidden_frozen<EXT_SUFFIX>

The resulting `.so` is committed; the source JSON and all intermediates are
gitignored and stay outside the tracked tree (see evaluation/hidden.py for the
loader and the runtime integrity check).

Usage:
    cd .github/skills/rag-eval-report/scripts
    python -m evaluation.tools.build_hidden
    python -m evaluation.tools.build_hidden --src /path/to/hidden_questions.json
"""
import argparse
import hashlib
import json
import marshal
import subprocess
import sys
import sysconfig
from pathlib import Path

TOOLS_DIR = Path(__file__).resolve().parent
SKILL_DIR = TOOLS_DIR.parents[2]  # .../rag-eval-report
DEFAULT_SRC = TOOLS_DIR.parent / "private" / "hidden_questions.json"
DEFAULT_ASSETS_DIR = SKILL_DIR / "assets"
BUILD_DIR = DEFAULT_ASSETS_DIR / "_build"
MODULE_NAME = "_hidden_frozen"

_REQUIRED_FIELDS = ("id", "question", "gold_answer", "gold_sources")


def _canonicalize(questions: list) -> list:
    """Sort by id so the fingerprint only reflects content, not file ordering."""
    for q in questions:
        missing = [f for f in _REQUIRED_FIELDS if f not in q]
        if missing:
            raise ValueError(f"question {q.get('id', '<no id>')} is missing field(s): {missing}")
    return sorted(questions, key=lambda q: q["id"])


def _fingerprint(questions: list) -> str:
    canonical_bytes = json.dumps(questions, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(canonical_bytes).hexdigest()


def _module_source(questions: list, digest: str) -> str:
    return (
        "# Auto-generated by build_hidden.py -- do not edit by hand.\n"
        f"QUESTIONS = {questions!r}\n"
        f"QUESTIONS_SHA256 = {digest!r}\n"
        f"QUESTION_COUNT = {len(questions)}\n"
    )


def _emit_c_source(code_bytes: bytes) -> str:
    lines = [f"0x{b:02x}" for b in code_bytes]
    rows = ",\n    ".join(", ".join(lines[i : i + 16]) for i in range(0, len(lines), 16))
    return f"""// Auto-generated by build_hidden.py -- do not edit by hand.
#include <Python.h>
#include <marshal.h>

static const unsigned char code_data[] = {{
    {rows}
}};
static const Py_ssize_t code_size = sizeof(code_data);

static struct PyModuleDef moduledef = {{
    PyModuleDef_HEAD_INIT, "{MODULE_NAME}", NULL, -1, NULL, NULL, NULL, NULL, NULL
}};

PyMODINIT_FUNC PyInit_{MODULE_NAME}(void) {{
    PyObject *code = PyMarshal_ReadObjectFromString((const char *)code_data, code_size);
    if (code == NULL) {{
        return NULL;
    }}
    PyObject *module = PyModule_Create(&moduledef);
    if (module == NULL) {{
        Py_DECREF(code);
        return NULL;
    }}
    PyObject *globals = PyModule_GetDict(module);
    PyObject *result = PyEval_EvalCode(code, globals, globals);
    Py_DECREF(code);
    if (result == NULL) {{
        Py_DECREF(module);
        return NULL;
    }}
    Py_DECREF(result);
    return module;
}}
"""


def build(src: Path, assets_dir: Path) -> Path:
    if not src.is_file():
        raise SystemExit(
            f"Hidden question source not found: {src}\n"
            "This is organizer-only data and is never committed to the repo."
        )
    data = json.loads(src.read_text(encoding="utf-8"))
    questions = _canonicalize(data["questions"])
    digest = _fingerprint(questions)

    code = compile(_module_source(questions, digest), f"<frozen {MODULE_NAME}>", "exec")
    code_bytes = marshal.dumps(code)

    BUILD_DIR.mkdir(parents=True, exist_ok=True)
    c_path = BUILD_DIR / f"{MODULE_NAME}.c"
    c_path.write_text(_emit_c_source(code_bytes), encoding="utf-8")

    ext_suffix = sysconfig.get_config_var("EXT_SUFFIX") or ".so"
    include_dir = sysconfig.get_paths()["include"]
    assets_dir.mkdir(parents=True, exist_ok=True)
    out_path = assets_dir / f"{MODULE_NAME}{ext_suffix}"

    # Remove stale builds for other module names/suffixes so only one copy of the frozen module exists.
    for stale in assets_dir.glob(f"{MODULE_NAME}*.so"):
        stale.unlink()

    cmd = ["cc", "-fPIC", "-shared", "-I", include_dir, "-o", str(out_path), str(c_path)]
    subprocess.run(cmd, check=True)

    return out_path, digest, len(questions)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--src", default=str(DEFAULT_SRC), help="Path to the private hidden_questions.json")
    parser.add_argument("--out-dir", default=str(DEFAULT_ASSETS_DIR), help="Directory to write the frozen .so into")
    args = parser.parse_args()

    out_path, digest, count = build(Path(args.src), Path(args.out_dir))
    print(f"\u2705 Froze {count} hidden questions -> {out_path}")
    print(f"   sha256: {digest}")


if __name__ == "__main__":
    if sys.platform not in ("linux",):
        raise SystemExit(f"build_hidden.py only supports Linux today (got {sys.platform!r}).")
    main()
